import "./index.css";
async function loadStyles() {
  const url = new URL("./index.css", import.meta.url);
  return (await fetch(url)).text();
}
function addStyles(textContent) {
  const id = "sideboard-styles";
  const el = document.head.querySelector(`#${id}`) ?? document.createElement("style");
  Object.assign(el, {
    textContent,
    id
  });
  document.head.append(el);
}
const doclist = {
  id: "chee/document-list",
  type: "patchwork:tool",
  name: "Document List",
  supportedDatatypes: ["folder"],
  icon: "FolderOpen",
  unlisted: true,
  async load() {
    const [{
      renderDocumentListPanel
    }, styles] = await Promise.all([import("./sideboard/document-list-panel.tsx"), loadStyles()]);
    return (handle, element) => {
      addStyles(styles);
      return renderDocumentListPanel(handle.url, element);
    };
  }
};
